export function getOdeirInformationSecurityContent(homeUrl='/odeir-preview'){
  const content=JSON.parse(JSON.stringify(informationSecurityDocument));
  const related=content.blocks.find(block=>block.id==='odeir-security-related');
  if(related){
    related.props.items[0].href=`${homeUrl}/privacy-policy`;
    related.props.items[1].href=`${homeUrl}/data-rights`;
  }
  return {
    title:'سياسة أمن المعلومات وحماية البيانات',
    seoTitle:'سياسة أمن المعلومات وحماية البيانات | أودير',
    seoDescription:'تعرف على نهج أودير وضوابطه لحماية المعلومات، والمسؤولية المشتركة، وإدارة الحوادث، والمرجعيات السعودية والدولية ذات الصلة.',
    content
  };
}

